-- Import secrétariat 2024
-- Source : Desktop/ngor almadies/YATAL/2024/
--   Yataal TRI 1er.xlsx, Yataal TRI 2 tri.xlsx, Yataal TRI 3 tri.xlsx,
--   Yataal TRI 4ème.xlsx (Feuil1 et Feuil2).
-- S'ajoute à l'import 2023 déjà en base. Les NICAD déjà enregistrés sont exclus.
--
-- Mêmes tables que le formulaire secrétariat :
--   dossiers, references_cadastrales, titulaires, terrains.
--   Pas d'attribution. txt_agentTraiteur reste vide.
--   Date d'état absente du classeur : 2024-12-31.
--
-- NICAD = code commune + section (3) + parcelle (5) + appartement (3).
--   Ngor 01130132, Ouakam 01130131, Yoff 01130133.
--   15 ou 18 chiffres commençant par 1130 : le zéro manquant est ajouté.
--   La date et le lieu de naissance sont séparés.
--
-- Doublon strict : même txt_num_titre, ou même titre mère avec le même lot.
--   Trim, majuscules, espaces autour du /. 15/S reste différent de S 15.
--   000 et 0 ne sont pas un lot. Un lot seul, ou un titre mère seul, n'est pas un doublon.
--   Deux NICAD différents pour le même triple sont conservés.
--   Un NICAD déjà présent en 2023 n'est pas réimporté.
--
-- Lignes lues : 6865
-- Lignes retenues : 291
-- Déjà en base (NICAD) : 6443
-- Déjà en base (même triple, sans NICAD nouveau) : 21
-- Même triple qu'en base, NICAD nouveau, conservées : 3
-- Ignorées : commune inconnue 0, vides 0
-- Doublons de triple écartés : 108
-- Même triple mais NICAD différent, conservées : 4
-- Doublons de NICAD écartés : 2
-- NICAD découpés : 253
-- Appartements : 0
-- Dates de naissance séparées : 153
-- Lieux de naissance : 159
-- Commune du fichier différente du préfixe : 3
-- Parcelle du fichier différente du NICAD : 3
-- NICAD illisible : 38
-- Par feuille retenue : TRI 4 Feuil1 266, TRI 1 Feuil1 15, TRI 4 Feuil2 10
-- Détail : rapport_import_secretariat_2024.txt
-- Identifiants à partir de 12406. Dossiers 00001/2024 et suivants.
-- N° d'ordre à partir de 12404.

SET NAMES utf8mb4;
START TRANSACTION;

































COMMIT;

-- Contrôle : NICAD = code commune + section + parcelle + appartement.
SELECT COUNT(*) AS nicad_incoherents FROM terrains t
JOIN communes c ON c.id = t.slt_commune
WHERE t.txt_nicad IS NOT NULL AND REPLACE(t.txt_nicad, ' ', '') <> CONCAT(
  REPLACE(c.txt_codeCommune, ' ', ''), IFNULL(t.txt_num_section, ''),
  IFNULL(t.txt_num_parcelle, ''), IFNULL(t.txt_appartement, ''));
